COMMENT ON COLUMN public.reviews.photos IS '사진(JSON: 사진 목록 · 대표 사진)';


--
-- Name: COLUMN reviews.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reviews.status IS '상태: DRAFT 임시저장 · PUBLISHED 게시중 · HIDDEN 미게시 · DELETED 삭제됨(휴지통)';


--
-- Name: COLUMN reviews.status_before_trash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reviews.status_before_trash IS '휴지통으로 옮기기 전 상태(복원하면 이 상태로 돌아감). 휴지통이 아니면 비어 있음';


--
-- Name: COLUMN reviews.author_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reviews.author_id IS '글을 올린 관리자(admin_users.id)';


--
-- Name: COLUMN reviews.deleted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reviews.deleted_at IS '휴지통으로 옮긴 시각(삭제됨일 때만)';


--
-- Name: reviews_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.reviews_id_seq
    START WITH 63
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: reviews_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.reviews_id_seq OWNED BY public.reviews.id;


--
-- Name: visit_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.visit_logs (
    id bigint NOT NULL,
    visited_on date NOT NULL,
    visitor_key character varying(64) NOT NULL,
    path character varying(300),
    device character varying(10),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: visit_logs_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.visit_logs ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.visit_logs_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


