COPY public.interviews (id, cohort, senior_name, track, title, summary, qa, video_url, video_length, photos, status, status_before_trash, author_id, published_at, created_at, updated_at, deleted_at) FROM stdin;
1	6	김**	AI 서비스 개발 A반	인천에서 내려와 개발반에서 창업을 준비해요	작년엔 주거 문제로 포기했던 인사교에 다시 지원했어요. 개발반에서 배우며, 무리한 다이어트를 막는 식단 · 체중 관리 서비스 창업을 준비하고 있어요.	[{"q":"간단한 자기소개 부탁드릴게요!","a":"안녕하세요. 인천에서 내려온 AI 서비스 개발 A반, 7반에서 배우고 있는 김**입니다."},{"q":"인천에서 오셨군요! 광주 인공지능사관학교를 위해 내려오셨나요?","a":"네, 맞습니다. 인공지능사관학교를 다니기 위해 내려왔어요."},{"q":"광주 인공지능사관학교(이하 인사교)를 아시게 된 계기가 궁금한데요?","a":"인사교에 대해서는 작년에도 알고 있었습니다. IoT 과정에 관심이 있어서 다녀보려고 했는데, 주거 문제 등 어려운 부분이 있어서 포기했었어요. 그런데 올해 인사교에서 먼저 문자가 왔더라고요. 과정도 약간 바뀌어 있고, 다시 관심이 생겨서 지원하게 되었습니다."},{"q":"개발반이시라면 코딩을 많이 배우시겠네요?","a":"네. 그런데 코딩을 처음 배운 건 아닙니다. \\"스타트업 스테이션\\"이라는 교육 과정에서 개발자와의 소통이 가능할 정도로 Python, HTML, CSS, JavaScript를 배웠습니다. 그래서 지금까지는 잘 따라가고 있어요."},{"q":"그럼 AI가 중심인 교육은 처음이실 것 같은데, AI를 배우기 전에는 AI에 대해 어떻게 생각하셨나요?","a":"네, AI가 중심인 교육은 처음입니다. 저는 사실 ChatGPT가 갑자기 유명해졌을 때 처음 써보고 바로 유료로 전환했어요."},{"q":"(ChatGPT를 바로 유료로 전환한) 이유가 뭔가요?","a":"그때 당시에 자소서를 작성하고 있었는데, 키워드만 입력하면 글을 알아서 작성해주고 제 글을 입력하면 문맥에 맞게 척척 고쳐주는 게 정말 신기하더라고요."},{"q":"그럼 AI를 배우고 난 지금은 AI에 대해 어떻게 생각하시나요?","a":"AI에 대해 정말 관심이 많아지고 시야가 넓어진 것 같아요. 항상 다른 사람이 만들어 놓은 표를 가져와서 썼는데, 이제는 제가 어떤 데이터를 알고만 있으면 금방 분석할 수 있다는 게 정말 신기해요."},{"q":"인사교를 다니면서 가장 좋았던 점은 무엇인가요?","a":"늦은 시간까지 공간을 이용할 수 있게 해주는 게 가장 좋은 점인 것 같아요. 집에 공부 환경이 잘 안 갖춰진 분들도 편하실 것 같고, 다른 분들과 많은 시간을 함께 보내는 것도 좋고요. 다만 지금은 주말에 9시부터 18시까지 개방해주시는데, 하루는 개인적인 시간을 보내고, 남은 하루를 9시부터 22시까지 집중 학습하는 것을 더 선호하는 것 같아요."},{"q":"공부하면서 힘들었던 점도 있으셨나요?","a":"처음에 과정을 선택하는 게 가장 힘들었어요. 자유롭게 과정을 선택할 줄 알았는데, TO가 나지 않으면 과정 변경이 어렵다고 들었습니다."},{"q":"그럼 개발반을 선택하게 된 과정은 어떠셨나요?","a":"저는 창업을 준비하면서 AI 비즈니스, AI 서비스 기획, AI 서비스 개발 중 하나를 고민하고 있었습니다. 사실 개발 과정의 강사님과 상담하는 동안까지도 다른 반을 생각하고 있었어요. 상담 후 \\"개발 엄청 재미있는데\\"라고 하며 나가셨을 때 강사님 표정이 너무 즐거워 보이셔서 선택하게 되었습니다."},{"q":"세준님은 현재 취업반이 아니라 창업반이신데, 창업반 모임 땐 어떤 활동을 하시나요?","a":"주로 영상 교육과 함께 사업 계획서를 작성합니다. 서로 피드백도 해주고, 대화도 많이 나누죠."},{"q":"(창업반 모임에) 따로 아쉬운 점은 없으세요?","a":"창업반의 모임은 하루 2시간 정도 주어지는데, 제가 원하는 합동 프로젝트 같은 걸 경험하기엔 너무 짧은 시간이라는 게 조금 아쉽긴 합니다."},{"q":"혹시 세준님께서 개발해보고 싶은 서비스가 따로 있으신가요?","a":"지금은 \\"AI 기반 강의 보정\\" 아이디어를 생각 중입니다."},{"q":"정확히 어떤 서비스인가요?","a":"예를 들어, 온라인 강의의 배속 재생을 사용할 때 목소리 톤이 올라가거나 음성이 거칠게 들릴 때가 있습니다. 그런 부분을 보정해주거나, 더 나아가서는 원하는 목소리로 강의를 들을 수 있게 하는 서비스입니다."},{"q":"만약 스크립트에 강의와 상관없는 내용이라면 AI가 판단해서 그 부분을 삭제해주기도 하고요?","a":"그렇죠. 만약 선호하는 목소리가 있다면, 그 설정대로 다른 강의도 같은 목소리로 들을 수도 있습니다. 열악한 환경에서 녹음되었다면, \\"음성만 또렷하게\\" 보정해서 들을 수 있게 하고 싶어요."},{"q":"이런 서비스처럼 AI와 사용자를 잘 연결하려면 어떤 점이 가장 중요하다고 생각하시나요?","a":"앞서 말씀드린 \\"스타트업 스테이션\\" 과정에서 했던 건데, 기획한 UX/UI를 프로토타입으로 만들어 사용해보고 다시 인터뷰를 진행하는 방식이 좋은 것 같습니다."},{"q":"약간 베타 테스트 같은 느낌인가요?","a":"네, 맞아요. 상황에 따라 기능 설명이 필요한지 여부를 보고, 사용자가 바로 사용하는지, 시간이 얼마나 소요되는지를 관찰한 뒤, 그렇게 된 이유를 평가하여 수정합니다."},{"q":"개발자의 입장에서 협업해보고 싶은 반이 있나요?","a":"앞에서 말씀드렸던 AI 기반 강의 최적화 서비스 같은 경우 자연어처리반과의 협업도 중요하겠지만, 결국 팀원과의 '핏(fit)'이 가장 중요하지 않을까 싶어요. ㅎㅎ \\"각자 잘하는 것에 집중하자\\"라는 말이 있듯이, 개발자는 기술적인 관점에 치우치다 보면 시장과 고객의 요구를 간과할 수도 있습니다. 그래서 기획반과의 협업도 필요하다고 생각합니다. \\"개발자는 개발에 집중, 기획자는 기획에 집중\\"하는 거죠."},{"q":"인사교 수료 후의 목표가 무엇인가요?","a":"생각해둔 아이템이 있어서 창업을 하려고 합니다."},{"q":"생각해둔 아이템에 대해 들을 수 있을까요?","a":"요즘 학생들도 그렇고, 너무 무리하게 다이어트를 해서 오히려 건강을 못 챙기는 사람들이 많잖아요. 건강을 해치지 않게 식단도 추천해주고 체중 관리를 도와주는 서비스를 만들어보고 싶어요. 감사합니다. 이곳에서의 배움이 오래도록 구상해온 이 아이템을 실현시킬 것이라 생각합니다."},{"q":"마지막으로 하고 싶은 말씀 있으신가요?","a":"오늘 너무 편하게 대해주셔서 감사합니다. 인터뷰하는 동안 너무 재밌었어요."}]	\N	\N	\N	PUBLISHED	\N	1	2026-10-19 14:27:07.475339	2026-10-19 14:27:07.475339	2026-10-19 14:27:07.475339	\N
10	6	김**	AI 비즈니스반	온라인으로 들은 비즈니스반, AI를 '어떻게 쓸지'를 배웠어요	데이터 분석 부트캠프를 거친 비전공자예요. 광주에 살지 않아 온라인으로 들었고, 생성형 AI를 비즈니스에 활용하는 방향을 잡았어요.	[{"q":"간단한 자기소개 부탁드려요!","a":"안녕하세요. 비즈니스반에서 공부 중인 김**입니다. 비전공자이고, 데이터 분석 부트캠프 경험이 있습니다. 이 분야에 관심이 많고 취업을 위해 입교하게 되었습니다."},{"q":"광주 인사교는 어떻게 알게 되셨나요?","a":"이전에 들었던 부트캠프의 연관 검색어로 인사교를 알게 되었어요. 광주 거주자가 아니어도 온라인으로 들을 수 있다고 해서 시작하게 되었습니다."},{"q":"이제 과정이 끝나가고 있으니 AI에 대해 많이 알게 되셨을 것 같은데, AI를 배우기 전에는 AI에 대해서 어떻게 생각하셨었나요?","a":"크게 달라졌다고는 생각하지 않아요. AI를 어떻게 다루느냐에 있어서 경쟁력이 생겼다고 생각합니다. AI를 어떻게 다루는지, 혹은 툴 하나하나를 세세하게 배우다 보니 그런 부분에 있어서 스킬이 늘었달까요?"},{"q":"그렇다면 과정이 끝나가는 지금은 AI에 대해 어떻게 생각하시나요?","a":"사실 저는 이전부터 ChatGPT나 Gemini를 많이 사용했어서 앞서 말씀드렸다시피 여기 와서 생각이 많이 달라지진 않았습니다."},{"q":"AI 비즈니스반을 고르신 이유가 궁금해요!","a":"현실적으로는 데이터 분석반 마감이 가장 큰 이유이긴 했어요. 차선으로 선택한 반이 비즈니스반인데 막상 배우고 나니 들어오길 잘했다는 생각이 들었어요. 딥러닝, 머신러닝 개념은 이미 알고 있어서 똑같은 내용을 배우는 것보단 비즈니스적으로 어떻게 활용할지 배우는 게 더 좋다고 느꼈거든요."},{"q":"비즈니스반에서 공부하시면서 지금까지 배운 것 중에 가장 인상 깊었던 내용이 있다면 무엇인가요?","a":"우선 강사님께서 정말 트렌디하세요! 단순히 사이트만 알려주시는 게 아니고 생성형 AI를 이용해서 직접 사용해보도록 가르쳐주시는 방식이 정말 좋아요. 어떻게 하면 투자적인 측면에서 도움이 될지 비즈니스 측면에서도 잘 도와주시고, 늘 '하나만 잘해선 안 된다'라고 강조를 하시는데 지금은 기술이 계속 발전하기 때문에 그것도 저는 맞다고 생각합니다."},{"q":"비즈니스반이시니 궁금한 게 있는데요, '돈이 되는 AI'라는 관점에서 봤을 때 따로 기억에 남는 수업 내용이 있으세요?","a":"음, 사실 전 창업이 목표는 아니에요. 하지만 만약 창업을 희망하는 사람이라고 생각한다면 투자자들에게 투자를 받는 게 중요하잖아요? 그만큼 투자자들을 설득하는 게 포인트라고 생각합니다. 그 방법은 다양한데, 저는 AI 툴을 이용해서 명확하게 제 생각을 보여줄 수 있다고 생각해요. 예를 들어, 태블로를 활용해 대시보드를 만들어서 제가 뭘 하고자 하는지 보여주는 느낌인 거죠. 생성형 AI를 다룬다면 핵심 기능을 빠른 시간 내에 만들어 구현이 가능하게끔 할 수 있고, 이것도 투자자들의 관점에서 봤을 때 '아, 이런 걸 하려는 거구나!' 하고 명확하고 빠르게 이해할 것 같아요!"},{"q":"AI 서비스를 기획하게 된다면 가장 고려해야 할 점은 어떤 거라고 생각하세요?","a":"이전 질문과 비슷한 결이라고 생각하는데, 서비스는 사용자의 입장에서 고려해야 하기 때문에 페인포인트 파악이 가장 중요한 것 같아요. 한마디로 '서비스의 필요성'이요."},{"q":"그럼 윤주님이 사용자의 입장일 때 AI가 불편했던 경험이 있으신가요?","a":"웬만하면 다 편하긴 했는데 AI가 제 말을 100% 다 알아듣고 답변을 주지는 않는다는 점? 요즘 '프롬프트 엔지니어'라는 직업이 있는 것처럼 프롬프트에 따라 답변이 달라지기 때문에 사용자의 역량 또한 중요하다고 생각합니다."},{"q":"AI를 활용해서 새로운 수익 모델을 만든다면 어떤 아이디어가 생각나시나요?","a":"이게 정말 어려운 질문인 것 같아요. 최근에 N8N이라는 자동화 툴을 배웠는데, 이걸 이용해서 자료 리서치를 할 때 반복적인 작업을 명령해서 할 수 있더라고요. 수익 모델이라고 하기엔 애매할 수 있지만 수익을 낼 수 있는 하나의 요소가 될 것 같습니다."},{"q":"비즈니스반이시라면 다른 직무와의 협업도 생각해보셨을 것 같은데, 인사교의 다른 반들 중에 함께 일해보고 싶은 반이 있으시다면요?","a":"지난 온라인 해커톤 때 다른 반과 처음으로 함께 협업을 해봤는데, 그때 컴퓨터 비전반 분들과 같이 작업을 했었어요. 모델링도 할 줄 아시고, 굉장히 다재다능하셔서 관심이 갔던 기억이 있어요!"},{"q":"요즘은 모든 시간을 프로젝트에 사용하지만 불과 한두 달 전까지는 커리어업 시간이 있었는데요, 커리어업 시간에 대해서 어떻게 생각하시나요?","a":"냉정하게 말하자면, 비교과 시간 중 기업탐방에 대해 그게 정말 크게 도움이 되었는지는 잘 모르겠어요. 평소에도 특강은 듣기보다는 개인적으로 자습을 하거나 프로젝트를 하고 있습니다."},{"q":"그럼 인사교를 다니며 가장 좋았던 점은요?","a":"온라인 교육으로 듣다 보니 시설은 잘 모르지만, 우선 저는 강사님에 대해 정말 만족하고 있어요. 단순히 'AI 툴은 이거다'에 그치지 않고 방향성을 어떻게 잡는지에 대해 배운 느낌이라 강사님을 너무 잘 만났다고 생각합니다!"},{"q":"반대로 교육을 들으며 불편했던 점은 없으셨나요?","a":"전체적으로 시스템이 더 체계적이었으면 좋겠어요. 멘토링과 출석체크 시간이 겹쳤던 상황이나 해커톤 수상 기준의 모호함 같은 부분에 있어서 조금 많이 아쉬웠습니다."},{"q":"마지막으로 수료 후 목표에 대해 들어볼게요!","a":"취업이 가장 우선적인 목표입니다. 제가 가지고 있는 지식과 배운 AI 툴을 활용해서 마케팅이나 데이터 애널리스트로 취업하고 싶습니다. 또 장기적으로는 창업도 생각하고 있어요!"}]	\N	\N	\N	PUBLISHED	\N	1	2026-10-19 14:27:07.81213	2026-10-19 14:27:07.81213	2026-10-19 14:27:07.81213	\N
12	6	국**	AI 서비스 기획반	코딩이 어려워 고른 기획반에서 개발 욕심이 생겼어요	코딩이 어려워 기획반에 지원했어요. 서비스 기획 과정과 Figma를 배우고 ADSP 필기에 합격했으며, 이제는 개발 역량도 키우고 싶어요.	[{"q":"인공지능사관학교에 지원하게 된 계기와 처음 입학했을 때 느낌은 어땠나요?","a":"광주 지역에서 AI 관련 지원자가 많다는 소식을 듣고 자연스럽게 관심이 생겼어요. 코딩이 어려워서 개발보다는 기획반에 지원하게 됐죠."},{"q":"3개월 차인 지금, 예상했던 것과 달라진 점이 있나요?","a":"처음에는 비대면 수업이었는데, 참여하는 분들을 보면서 '나도 열심히 해야겠다'는 마음이 컸어요. 수업을 듣다 보니 부족한 점을 많이 느꼈고, 지금은 개발 쪽 역량도 키워보고 싶은 욕심이 생겼답니다."},{"q":"가장 흥미로웠던 수업이나 주제는 무엇이었나요?","a":"기업 연계 프로젝트에서 아기 두상을 판별해서 진단을 하는 주제가 정말 신선했고, 사업적으로도 활용 가능성이 크다고 느꼈어요."},{"q":"서비스 기획반에서 주로 배운 점과 특징은 무엇인가요?","a":"서비스 기획의 단계별 과정과 함께 Figma 사용법을 배웠어요. 서비스 기획이 서비스 전반을 설계하는 일이다 보니 디자이너와 근접한 역할을 하게 된다는 점이 인상적이었어요."},{"q":"수업이나 프로젝트 진행 중에 어려웠던 점과 극복 방법은?","a":"온라인 해커톤에서 다양한 분야 사람들과 협업하다 보니 부족함을 많이 느꼈습니다. 하지만 서로 배운 점이 다름을 인정하며 각자의 분야에서 최선을 다했어요."},{"q":"과정 중 자격증 취득이나 성취한 성과가 있나요?","a":"ADSP 자격증 필기 시험에 합격했고, 빅데이터분석기사 실기를 준비하고 있어요. 추가로 토익 점수를 올리기 위해 노력 중입니다."},{"q":"과정을 수료한 후 어떤 계획이 있나요?","a":"첫째는 관련 직종에 취업하는 것이고, 둘째로는 개발 쪽 영역도 더 깊이 공부하며 발을 담그고 싶어요."}]	\N	\N	\N	PUBLISHED	\N	1	2026-10-19 14:27:07.854208	2026-10-19 14:27:07.854208	2026-10-19 14:27:07.854208	\N
2	6	정**	자연어 처리반	'또 다른 언어를 배우나?' 싶던 자연어처리로 취업을 준비해요	데이터 분석에 관심이 있었지만 자연어처리반에서 시작했어요. 비전공자라 따라가기 힘들었지만 강사님께 묻고 또 물으며, 이제는 이 분야로 취업하고 싶어요.	[{"q":"간단하게 자기소개부터 부탁드려요!","a":"안녕하세요. 인공지능사관학교 자연어처리반에서 교육을 받고 있는 교육생 정**입니다."},{"q":"인사교엔 어떻게 지원하게 되셨나요?","a":"인사교에 오기 전에 스마트인재개발원에서 6개월 정도 AI 관련 교육을 받았었는데요. 당시 선생님을 통해 소식을 들었어요. AI에 대해 더 알고 싶어서 지원했습니다."},{"q":"그러면 자연어처리반은 직접 선택해서 들어가신 건가요?","a":"아니요, 직접 선택한 반은 아닙니다. 사실 원래는 데이터 쪽에 관심이 많아요."},{"q":"데이터 쪽에 관심이 많으시다면 원래는 데이터 분석반을 희망하셨겠네요?","a":"네, 맞아요. 그런데 통화로 합격 통지를 받았을 때, 이 분야가 앞으로 전도유망할 거고 다방면으로 많이 쓰이는 분야라고 하셔서 결정했습니다."},{"q":"AI에 대해 스마트인재개발원에서도 배우시고 인사교에서 한 번 더 깊게 배우고 계시는데, 혹시 AI를 배우기 전에는 AI에 대해 어떻게 생각하셨나요?","a":"알고는 있었지만 사실 제대로 써본 적은 없어요. 기가지니나 ChatGPT 같은 걸 보며 그냥.. 똑똑한 로봇이구나.. 이 정도로만 생각했죠."},{"q":"그럼 AI를 배운 지금은 어떠세요?","a":"뭐랄까, AI에 대한 환상이 깨졌다고나 할까요? ㅎ 근데 또 동시에, 생각 이상으로 세분화가 되어 있고 종류가 엄청 다양해서 놀랐어요. 원래는 그냥 대화해주는 기계 느낌이었는데, 알고 보니 유튜브 알고리즘, 번역에까지 쓰이길래 생각보다 유용하다고 느꼈습니다."},{"q":"현희님은 '자연어처리'라는 걸 처음 접했을 때 어떠셨어요?","a":"솔직히 말씀드리면 '이게 무슨 말이지? 또 다른 언어를 배우는 건가..?'라고 생각했습니다 ㅋㅋㅋ"},{"q":"자연어처리반에서는 어떤 걸 배우나요?","a":"처음엔 간단한 판다스, 머신러닝 등을 배웠습니다. 그리고 지금은 구글 코랩을 통해 파이썬을 이용해서 파이토치(PyTorch), 파인튜닝(Fine-Tuning), 그리고 텍스트 마이닝(text mining)을 배우고 있어요. 사실 배울수록 개념은 점점 심화되기 때문에 저도 모든 걸 알고 있진 않은 것 같습니다 ㅎ"},{"q":"혹시 지금 배우시는 '텍스트 마이닝'에 대해서 아주 간단하게 설명해주실 수 있나요?","a":"우리의 언어를 기계가 어떤 언어인지 알아듣게 하는 게 '자연어처리'인데요, '텍스트 마이닝'은 비정형화된 언어를 인공지능이 어떤 의미인지 알아듣게 하기 위해서 텍스트를 정리하는 기술입니다."},{"q":"우리의 언어를 인공지능이 알아듣는다고 하니 '챗봇'이 가장 먼저 떠오르는데요, 이 기술을 알게 된 후 '챗봇'에 대해 생각이 바뀌신 게 있나요?","a":"'자연어처리'를 배우기 전에는 AI가 문장을 구사하는 게 그저 당연한 건 줄 알았는데, 이제는 '아, 인공지능이 우리와 대화할 수 있는 게 간단하지 않고 이러한 과정을 거치는 거구나'라고 생각하게 되었습니다."},{"q":"'커리어업' 시간에 대해서 어떻게 생각하시나요?","a":"인사교의 '커리어업' 시간은 신기하기도 하고 굉장히 유용하다고 느끼고 있어요. 최근 멘토님들께서 이력서를 봐주셨는데, 확실히 '커리어업'이라는 이름이 잘 어울린다고 생각했어요."},{"q":"학교를 다니며 '인공지능사관학교' 자체에 대해 가장 좋았던 점이 있었다면 무엇인가요?","a":"개인적으로 가장 좋았던 점은 '시설'이에요. 건물도 깔끔하고, 특히 1층에 있는 카페테리아가 가장 좋아요. 넓어서 앉을 자리도 많고, 각종 시설들이 있는데, 그중 제빙기가 있는 게 제일 좋은 것 같습니다."},{"q":"그럼 반대로 힘들었던 점도 있으셨나요?","a":"아무래도 제가 비전공자이다 보니 교육 내용을 따라가는 것이 가장 힘들었습니다. 그래도 강사님께서 질문을 하면 잘 받아주셔서 열심히 따라가려고 하고 있어요."},{"q":"수료 후의 목표가 있으실까요?","a":"저는 취업반이다 보니, 역시 목표는 취업입니다. 현재 배우고 있는 '자연어 처리' 기술 쪽으로 취업을 하고 싶어요."},{"q":"인터뷰를 끝내기 전에 정말 마지막으로 하고 싶으신 말씀이 있으시다면요?","a":"저의 단기적 목표인데요, 인사교 우수 수료생이 되어 인턴십에 뽑히고 싶어요. 실무 경험을 쌓고 꼭 취업하고 싶습니다!"}]	\N	\N	\N	PUBLISHED	\N	1	2026-10-19 14:27:07.625909	2026-10-19 14:27:07.625909	2026-10-19 14:27:07.625909	\N
3	6	노**	AI 서비스 기획반	외교학 전공, AI는 남의 일인 줄 알았어요	AI는 연구실 사람들의 일이라고 생각했던 외교학 전공자예요. 기획반에서 데이터 분석부터 UX 시나리오까지 배우며 막연한 두려움이 사라졌어요.	[{"q":"간단한 자기소개 먼저 부탁드리겠습니다.","a":"안녕하세요. AI 서비스 기획반에서 공부하고 있는 노**이라고 합니다."},{"q":"먼저 인사교를 알게 된 계기부터 여쭤볼게요!","a":"인사교를 홍보하는 블로그 글을 봤습니다. 홍보 포스터를 보고 지원하게 되었어요."},{"q":"원래도 AI에 관심이 많으셨나요?","a":"아니요, AI는 너무 전문가들의 영역이라고 생각해서 원래는 크게 관심이 있지는 않았습니다."},{"q":"그럼 어떻게 관심을 가지고 지원하게 되셨고, 기존 전공은 무엇인지 궁금합니다.","a":"최근 들어 하도 AI, AI 하는 걸 보니 조금 친숙함을 느꼈던 것 같아요. 원래 전공은 외교학입니다."},{"q":"AI를 배우기 전에는 AI에 대해 어떻게 생각하셨나요?","a":"정말 그냥, 나와 상관없는 것? 연구실에서 머리 싸매고 공부해야 하는 느낌 있잖아요. 나와는 정말 관련이 없다, 라고 생각했어요."},{"q":"그럼 AI를 사용해 보신 적 있으셨나요?","a":"ChatGPT 정도는 써 봤습니다. 작년까지 학원에서 아이들을 가르쳤는데, 기존 수업 교재 내용을 어떻게 하면 쉽게 가르칠 수 있을지 보조 도구로 사용했어요."},{"q":"이제는 AI를 어느 정도 배우셨을 텐데, 지금은 어떻게 생각하고 계시나요?","a":"음, 생각보다 별거 없다? 하지만 어렵다. '어렵다. 할 수 있을까?'라고 생각했었는데, 막상 머신러닝/딥러닝까지 배워 보니까 어렵기는 해도 막연한 두려움은 사라졌습니다."},{"q":"현재 기획반에서 교육을 받고 계시는데, AI 서비스 기획반을 선택하신 이유가 있나요?","a":"1지망 기획, 2지망 비즈니스였는데, 온라인 수업 때 트랙 설명회를 듣고 기획반이 더 잘 맞을 것 같았고, 수료 후에도 다양한 방면에서 활용할 수 있을 것 같아서 선택했습니다."},{"q":"그렇다면 이 인터뷰를 보실 다른 분들을 위해 기획반에서 지금까지 어떤 걸 배우셨는지 소개해 주실 수 있나요?","a":"데이터 분석에서 어떻게 기획으로 이어지는지를 배웠어요. 어떤 서비스를 구체적으로 분석해서 시각화도 해 보고, 그걸 발표하는 시간도 많이 가졌습니다."},{"q":"그럼 지금 배우고 계시는 내용은 무엇인가요?","a":"가장 최근에는 서비스 가치 흐름도와 비즈니스 모델 캔버스라는 것에 대해 배웠습니다. 지금 배우는 교과목이 'AI 비즈니스 기획'이거든요."},{"q":"인사교 기획반에서 배우는 걸 궁금해하시는 분들을 위해서 해당 교과목에 대해 간단하게 설명해 주실 수 있을까요?","a":"말 그대로 비즈니스, 마케팅 분야에서 AI가 어떻게 사용되는지 분석도 해 보고 직접 기획도 해 보는 수업을 진행하고 있습니다."},{"q":"대면 수업을 진행한 지 약 2개월이 지났는데요, 지금까지 배우신 내용 중에 가장 재밌었거나 인상 깊었던 수업이 있었나요?","a":"'UX 시나리오' 교과목에서 배운 페르소나 만들기요. 가상의 인물을 정해서 직접 인격을 부여한다는 게 재밌었어요."},{"q":"그러면 반대로 교과목 중 어려웠던 파트도 있으셨나요?","a":"대면 수업 초반에 배운 데이터 분석이 조금 어려웠는데, 그래도 기획 파트를 배우면서 조금씩 수월해졌어요."},{"q":"그럼 기획 파트를 배우면서 '아, 이런 AI 서비스를 기획해 보고 싶다'라고 생각해 보신 것 있나요?","a":"구체적으로 생각해 본 적은 없지만, 최근 비즈니스 모델 캔버스를 배우면서 뷰티 분야에 관심이 많아졌어요."},{"q":"최근 진행한 프로젝트에서 뷰티와 관련된 서비스를 기획하셨었죠?","a":"네, 그렇습니다. 그 아이디어도 제가 낸 거예요!"},{"q":"그럼 AI와 UX를 잘 연결하려면 어떤 점이 중요하다고 생각하시나요?","a":"평소에도 서비스를 사용자의 관점에서 바라보는 시각이 가장 중요하다고 생각합니다."},{"q":"조금 더 구체적으로 말씀해 주실 수 있나요?","a":"저도 수업을 듣기 전에는 별생각 없이 서비스를 이용했는데, 신기하게도 수업 후에는 '나였다면 이런 점은 어떻게 개선했을까?' 이런 생각을 자주 하게 되었어요. '이런 건 편하지만, 저런 기능을 추가하면 좋겠다'와 같이 평소에도 다양한 관점으로 보는 게 중요한 것 같습니다."},{"q":"그런 생각을 많이 하셨다면 인사교에 있는 다른 반과의 협업도 생각해 보셨을 것 같은데, 함께 작업해 보고 싶은 반이 있으신가요?","a":"제가 분석 쪽이 약해서 데이터 분석반과 함께 하면 좋은 시너지가 날 것 같고, 또 제가 기획한 걸 토대로 개발반과 함께 직접 개발해 보는 것도 재밌을 것 같습니다."},{"q":"인사교를 다니면서 가장 좋았던 점은 무엇인가요?","a":"가장 좋은 건 오프라인으로 수강하면 다른 사람들과 함께 수업을 들을 수 있는 점이에요. 온라인으로 들었다면 몸은 편했겠지만 매일이 똑같은 루틴이라 지루했을 것 같거든요. 오프라인은 몸이 조금 힘들 수 있지만, 쉬는 시간이나 점심시간마다 사람들과 어울리며 그 힘듦을 털어낼 수 있어서 좋습니다!"},{"q":"그럼 반대로 공부하며 힘들었던 점도 있으세요?","a":"수업 초반, 데이터 분석이 너무 어려웠습니다. 사실 지금도 어렵지만, 그래도 이제는 코드를 보면 대충 무슨 내용인지 이해는 갑니다. 수업 내용을 머릿속에 집어넣으려고 노력하고, ADsP 자격증 공부를 병행한 게 도움이 됐었어요."},{"q":"마지막 질문입니다! 인사교 수료 후의 목표가 있으시다면요?","a":"일단 끝까지 달려서 수료하는 것 자체가 목표이긴 합니다. 그리고 꼭 AI 서비스 기획자가 되지 않더라도, 이 과정에서 잘 배우고 제가 가진 기술들과 합해진다면 더 큰 가능성을 가진 사람이 될 것 같아요."}]	\N	\N	\N	PUBLISHED	\N	1	2026-10-19 14:27:07.654385	2026-10-19 14:27:07.654385	2026-10-19 14:27:07.654385	\N
4	6	손**	자연어 처리 A반	LLM을 쓰던 사람에서 구조를 들여다보는 사람으로	일하며 GPT 같은 툴을 자주 쓰다 보니 구조 자체가 궁금해졌어요. 랭체인 · 랭그래프를 경험하며 커리어 목표가 서버 운용에서 LLM으로 바뀌었어요.	[{"q":"인공지능사관학교에 지원하게 된 계기와 처음 입학했을 때 느낌은 어땠나요?","a":"일을 하면서 GPT나 LLM 같은 툴을 자주 사용하다 보니, 단순히 쓰는 걸 넘어서 구조 자체를 뜯어보고 싶다는 호기심이 생겼습니다."},{"q":"3개월 차인 지금, 예상했던 것과 달라진 점이 있나요?","a":"처음 들어와 보니 생각보다 체계적으로 커리큘럼이 구성돼 있어서 놀랐고, 광주라는 도시 자체도 생활하기에 괜찮다는 인상을 받았습니다. 심화 과정까지는 아니었지만, 최신 기술까지 접할 수 있었던 점에서 충분히 만족스러웠습니다."},{"q":"가장 흥미로웠던 수업이나 주제는 무엇이었나요?","a":"랭체인과 연결된 랭스미스, 랭그래프를 처음 경험해봤는데, 이 부분이 특히 흥미로웠습니다."},{"q":"자연어 처리반에서 주로 배운 점과 특징은 무엇인가요?","a":"딥러닝과 머신러닝 전반을 배우지만, 특히 자연어처리 분야에서 문맥별 감정 분류(토큰 기반)에 집중적으로 다뤘던 점이 인상 깊었습니다."},{"q":"수업이나 프로젝트 진행 중에 어려웠던 점과 극복 방법은?","a":"대부분이 쉽지 않았지만, 문서가 잘 정리돼 있었고 외국 포럼이나 논문을 직접 찾아보면서 이해하고 극복했습니다."},{"q":"과정 중 자격증 취득이나 성취한 성과가 있나요?","a":"자격증 취득보다는 학습 자체에 더 집중했습니다."},{"q":"협업 프로젝트나 팀 활동에서 배운 교훈이 있다면?","a":"팀 프로젝트를 통해 “자신이 맡은 일은 확실히 책임지고, 모르면 바로 물어보며 소통하는 것”이 가장 중요하다는 교훈을 얻었습니다."},{"q":"자연어 처리반을 추천한다면 어떤 사람에게 어울릴까요?","a":"자기주도적으로 학습할 수 있고, 새로운 도전에 두려움이 없는 분들에게 추천하고 싶습니다. 실습과 프로젝트 위주라서 적극적으로 참여할수록 얻는 게 많습니다."},{"q":"인사교 과정을 수료한 후 어떤 계획을 가지고 있나요?","a":"과정을 마친 뒤에는 석사 학위 과정을 밟고, 그 후에 관련 분야로 취업하고 싶습니다."},{"q":"이 과정을 통해 본인의 커리어 목표가 어떻게 달라졌나요?","a":"원래는 서버 운용 분야에 관심이 있었는데, 이번 과정을 통해 대규모 언어 모델(LLM) 쪽으로 커리어 목표가 확실히 바뀌었습니다."}]	\N	\N	\N	PUBLISHED	\N	1	2026-10-19 14:27:07.683102	2026-10-19 14:27:07.683102	2026-10-19 14:27:07.683102	\N
5	6	박**	컴퓨터 비전반	바이오에서 비전 AI로, 커리어 시야가 넓어졌어요	바이오 분야 경험을 살려 새로운 도전을 시작했어요. 비전공자라 코딩이 가장 어려웠지만 손으로 반복하며 익혔고, 미니 · 팀 프로젝트를 해내며 실력을 키웠어요.	[{"q":"인공지능사관학교에 지원하게 된 계기와 처음 입학했을 때 느낌은 어땠나요?","a":"제가 실업 상태였을 때, 평소에 인공지능 사업이 정말 크게 부흥하고 있다는 이야기를 많이 들었어요. 그러던 중에 인공지능사관학교 모집 소식을 듣게 되었고, 바이오 분야에 있었던 경험을 살려서 새로운 도전을 해보고 싶어서 지원하게 되었습니다. 처음 들어왔을 때는 6개월이라는 긴 커리큘럼을 제가 과연 다 소화할 수 있을까 하는 걱정과 동시에 새로운 배움에 대한 기대감이 있었던 것 같아요."},{"q":"3개월 차인 지금, 예상했던 것과 달라진 점이 있나요?","a":"사실 처음에 6개월 커리큘럼이 이렇게 깊이 있고 다양할 줄은 예상하지 못했어요. 단순히 지식 전달을 넘어 실전 위주의 교육이라 저한테는 의외의 배움의 연속이었던 것 같아요."},{"q":"가장 흥미로웠던 수업이나 주제는 무엇이었나요?","a":"음, 프론트엔드와 백엔드 개발을 모두 배울 수 있었던 점이 인상 깊었어요. 덕분에 전체적인 시스템을 이해하는 시야가 넓어진 것 같고요. 특히 비전 모델이나 멀티모달 기술을 접할 때마다, ‘아, 이건 진짜 인공지능사관학교 아니면 쉽게 접할 수 없었겠다’는 생각이 들면서 너무 신기하고 재미있었습니다."},{"q":"컴퓨터 비전반에서 주로 배운 점과 특징은 무엇인가요?","a":"특히 비전 모델 쪽에 특화되어 있었던 것 같아요. 이 분야는 아무래도 많은 자원과 지원이 필요하다는 특징이 있잖아요. 그런 환경 속에서 눈으로 직접 보이는 결과물을 만들 수 있다는 점이 더 신선하고 흥미로웠어요. 이론뿐만 아니라 실제 구현 과정을 통해 직관적으로 기술을 익힐 수 있었던 게 큰 장점이라고 생각합니다."},{"q":"수업이나 프로젝트 진행 중에 어려웠던 점과 극복 방법은?","a":"제가 비전공자이다 보니 코딩이 가장 큰 어려움이었어요. 특히 수업을 따라가면서 코드를 직접 쳐야 하는데, 오타가 많이 생기곤 했죠. 하지만 꾸준히 반복하고 계속해서 손으로 코딩하다 보니 어느 순간부터 익숙해지고 자연스러워지는 것을 느꼈습니다. 반복 학습의 중요성을 깨달은 시간이었어요."},{"q":"과정 중 자격증 취득이나 성취한 성과가 있나요?","a":"자격증에 따로 시간을 투자할 여유는 솔직히 없었어요. 하지만 저는 미니 프로젝트와 팀 프로젝트들을 성공적으로 수행해나가면서 6개월 과정에서 얻을 수 있는 것들을 최대한 얻었다고 생각해요. 이론만 배우는 게 아니라, 직접 프로젝트를 기획하고 구현하는 과정을 통해 진짜 ‘실력’을 키웠다고 자부합니다!"},{"q":"협업 프로젝트나 팀 활동에서 배운 교훈이 있다면?","a":"팀원들과 함께 여러 프로젝트를 진행하면서, 기술적인 역량도 물론 중요하지만, 여러 사람과 협력할 때 나오는 시너지가 정말 엄청나다는 것을 깨달았어요. 혼자서는 해결하기 어렵거나 오래 걸리는 문제들도, 함께 머리를 맞대고 의논하니 훨씬 쉽고 효율적으로 해결되는 경험을 많이 했습니다."},{"q":"컴퓨터 비전반을 추천한다면 어떤 사람에게 어울릴까요?","a":"평소에 기계나 새로운 기술에 관심이 많고, 직접 만들고 구현하는 것을 좋아하는 분이라면 정말 잘 맞을 거예요. 이 과정에서 배우는 기술들이 실생활과 연결될 때 더 큰 재미를 느낄 수 있을 거라고 생각합니다."},{"q":"인사교 과정을 수료한 후 어떤 계획을 가지고 있나요?","a":"사실 이 질문이 지금 제일 많이 고민되는 부분이긴 합니다. 아직 정확하게 어떤 방향으로 나아갈지 계속해서 탐색하고 있지만, 이 과정에서 배운 것들을 바탕으로 제가 잘하고 흥미를 느낄 수 있는 분야를 찾아서 더 깊이 있게 공부해보고 싶어요."},{"q":"이 과정을 통해 본인의 커리어 목표가 어떻게 달라졌나요?","a":"인공지능사관학교에 오기 전에는 막연히 제가 원래 전공했던 분야를 고수해야겠다고 생각했었어요. 그런데 이 과정을 통해 제가 몰랐던 새로운 적성과 가능성을 발견하게 되었고, 이제는 특정 분야에만 갇히지 않고 더 넓은 기회를 열어 두고 탐색해야겠다는 생각으로 바뀌었습니다. 제 커리어에 대한 시야가 훨씬 넓어진 거죠!"}]	\N	\N	\N	PUBLISHED	\N	1	2026-10-19 14:27:07.707623	2026-10-19 14:27:07.707623	2026-10-19 14:27:07.707623	\N
8	6	이**	AI 클라우드·인프라반	기계공학 전공자가 인프라반에서 찾은 새 진로	진로를 정하지 못한 채 새로운 분야를 찾아 지원했어요. 리눅스와 서버 구축을 익히고 ADSP 자격증을 따며 데이터 · 인프라로 시야를 넓혔어요.	[{"q":"인공지능사관학교에 지원하게 된 계기와 처음 입학했을 때 느낌은 어땠나요?","a":"졸업 후 진로 방향을 정하지 못한 상태에서, 새로운 분야를 탐색하기 위해 지원했습니다. 기계공학 전공이라 AI는 낯설었지만, 막상 들어와 보니 생각보다 서버 구축이나 인프라 중심의 커리큘럼이 많아 의외였습니다. AI적인 내용보다는 실무 인프라 쪽 비중이 높다는 점이 처음에는 예상 밖이었어요."},{"q":"3개월 차인 지금, 예상했던 것과 달라진 점이 있나요?","a":"처음엔 AI 중심으로 배울 줄 알았는데, 실제로는 서버 환경 구축, 데이터 분석 등 기반 기술을 배우는 데 더 초점이 맞춰져 있었습니다. 결국 데이터 분석(1순위)과 인프라(2순위)를 함께 배운 덕분에 커리어의 확장성을 더 넓게 볼 수 있었어요."},{"q":"가장 흥미로웠던 수업이나 주제는 무엇이었나요?","a":"AWS 특강이 가장 흥미로웠습니다. 실습 중심으로 진행되어 실제 시스템을 다루는 감각을 키울 수 있었고, 실무와 바로 연결되는 경험이었어요."},{"q":"AI클라우드 및 인프라트랙 반에서 주로 배운 점과 특징은 무엇인가요?","a":"저희 반은 다른 반보다 리눅스 환경을 잘 다루는 점이 특징입니다. 인프라 구축, 서버 관리 등 백엔드 기반의 실무 경험을 많이 쌓을 수 있었어요."},{"q":"수업이나 프로젝트 진행 중에 어려웠던 점과 극복 방법은?","a":"초기에는 서버 인프라 개념이 익숙하지 않아 학습 진도를 따라가기 어려웠습니다. 또 같은 인프라 반이다 보니 기술 스택이 겹쳐서 확장이 어렵게 느껴졌는데, 반복 학습과 실습을 통해 점차 익숙해졌습니다."},{"q":"과정 중 자격증 취득이나 성취한 성과가 있나요?","a":"ADSP(데이터분석준전문가) 자격증을 취득했고, 현재 AWS와 네이버 관련 자격증을 준비 중입니다."},{"q":"협업 프로젝트나 팀 활동에서 배운 교훈이 있다면?","a":"'무조건 시간을 많이 쏟는 게 좋은 결과로 이어지진 않는다'는 걸 깨달았습니다. 적절한 워라밸을 유지했을 때 오히려 집중력이 높아지고 성과도 더 좋았습니다."},{"q":"AI클라우드 및 인프라반을 추천한다면 어떤 사람에게 어울릴까요?","a":"비전공자에게 추천하고 싶습니다. 다른 개발반은 기본적인 코딩 실력을 요구하는 반면, 인프라 반은 기초부터 실무 환경을 배우는 과정이라 입문자도 충분히 따라올 수 있습니다."},{"q":"인사교 과정을 수료한 후 어떤 계획을 가지고 있나요?","a":"현재는 취업 준비 중이며, 데이터 분석과 인프라 분야를 중심으로 지원하고 있습니다."},{"q":"이 과정을 통해 본인의 커리어 목표가 어떻게 달라졌나요?","a":"이전에는 기계 분야에만 머물러 있었는데, 이번 과정을 통해 데이터와 인프라 등 다양한 직무로 시야가 넓어졌습니다. 결국 제 진로 선택에 실질적인 도움이 되었다고 생각합니다."}]	\N	\N	\N	PUBLISHED	\N	1	2026-10-19 14:27:07.77329	2026-10-19 14:27:07.77329	2026-10-19 14:27:07.77329	\N
9	6	익명	컴퓨터 비전 A반	프로젝트 경험을 찾아 와서 협업을 배웠어요	졸업 후 취업을 준비하며 프로젝트 경험이 필요해 인사교를 골랐어요. 기업 연계 프로젝트와 멘토링으로 협업 능력과 실무 감각을 키웠어요.	[{"q":"간단한 자기소개 부탁드립니다.","a":"안녕하세요. 컴퓨터비전 A반에서 학습 중인 교육생입니다. 현재는 데이터 분석과 개발 PM(Project Manager) 분야에 관심이 많습니다."},{"q":"인공지능사관학교에 참여하게 된 계기는 무엇인가요?","a":"졸업 후 취업을 준비하면서 프로젝트 경험의 중요성을 크게 느꼈습니다. 여러 부트캠프를 알아보다가 인공지능사관학교를 선택하게 되었는데요, 무엇보다도 주거 지원비 등 금전적 지원과 다양한 수강생 혜택이 매력적이었습니다. 또한 단순한 이론 학습이 아닌, 팀 프로젝트를 통한 실무 중심의 경험을 쌓을 수 있다는 점이 큰 장점이라고 생각했습니다. 프로젝트 기반으로 포트폴리오를 채우며 자격증 취득 등 취업 역량을 강화할 수 있다는 점에서 인사교만의 체계적인 커리큘럼이 마음에 들었습니다."},{"q":"요즘 가장 흥미롭게 배우고 있는 부분은 무엇인가요?","a":"현재 진행 중인 기업 연계 프로젝트가 가장 흥미롭습니다. 처음부터 개발 단계까지 직접 참여하며 실무와 밀접한 기술 및 협업 경험을 쌓을 수 있다는 점이 큰 배움이 되고 있습니다. 또한 멘토님과의 대화를 통해 현업에서 사용하는 문서 작성 방식, 프로젝트 진행 순서와 프로세스, 의사소통 방식 등을 배우며 단순히 기술적인 역량뿐 아니라 실제 산업 현장에서 필요한 감각도 익히고 있습니다. 무엇보다도 팀 프로젝트를 통해 다양한 협업 툴을 익히고, 협업 능력을 발전시킬 수 있었다는 점이 매우 만족스러웠습니다."},{"q":"Talk Up 행사에 참여해보니 어떤 점이 인상 깊었나요?","a":"인사교의 소통 구조가 정말 잘 되어 있다고 느꼈습니다. 건의사항이나 질문이 생겼을 때 익명으로 편하게 의견을 전달할 수 있고, 이에 대해 빠르고 세심한 피드백을 받을 수 있다는 점이 인상 깊었습니다. 교육생의 목소리를 진심으로 반영하려는 운영진의 태도가 학교에 대한 신뢰감을 더 크게 만들어 주었습니다."},{"q":"앞으로 AI 분야에서 어떤 커리어를 쌓고 싶나요?","a":"AI는 이미 여러 산업에서 생산성과 효율성을 높이는 필수 기술이 되었다고 생각합니다. 앞으로는 AI를 적극적으로 활용해 원하는 분야에서 더 높은 성과를 낼 수 있는 사람이 되고 싶습니다. 단순히 기술을 배우는 것에 그치지 않고, AI를 실질적으로 업무에 녹여내고 문제를 해결할 수 있는 역량을 갖추는 것이 목표입니다."},{"q":"사관학교에서의 경험이 진로에 어떤 도움이 되었나요?","a":"가장 크게 성장한 부분은 협업 능력과 실무 감각입니다. 프로젝트를 직접 진행하면서 데이터 분석, 모델 개발 역량뿐 아니라 팀원들과의 커뮤니케이션 능력이 크게 향상되었습니다. 또한 사관학교에서 디스코드, 노션 등 다양한 협업 툴을 적극적으로 활용할 수 있었던 점도 좋았습니다. 이러한 경험 덕분에 앞으로 회사에서도 팀원 및 이해관계자와 원활하게 협력할 수 있을 것이라 자신하게 되었습니다."},{"q":"함께 공부하는 동료들에게 한마디 해주신다면요?","a":"이제 교육이 한 달 정도밖에 남지 않았는데요, 모두 건강 잘 챙기고 끝까지 함께 완주했으면 좋겠습니다. 지금까지 함께 달려온 시간만큼, 마지막까지 서로 응원하며 좋은 결과를 만들어갔으면 합니다."}]	\N	\N	\N	PUBLISHED	\N	1	2026-10-19 14:27:07.79095	2026-10-19 14:27:07.79095	2026-10-19 14:27:07.79095	\N
6	6	권**	데이터 분석반	경영학 전공자가 서울에서 내려와 데이터를 배워요	IT로 진로를 넓히려고 서울에서 내려왔어요. 주거비 · 식비 지원을 보고 인사교를 골랐고, 경영 통계 경험을 살려 데이터 분석을 배우고 있어요.	[{"q":"간단한 자기소개 부탁드려요!","a":"안녕하세요. 서울에서 내려온 권**입니다."},{"q":"광주의 인사교는 어떻게 알게 되셨나요?","a":"기존 업무 영역을 확장하거나 IT 쪽으로 진로를 바꾸고 싶다고 생각하며 부트캠프를 알아보던 중에 '광주인공지능사관학교'를 알게 되었습니다."},{"q":"많은 부트캠프들 중에 인사교를 고르신 이유가 있나요?","a":"주거비와 식비를 지원해 주고, 내일배움카드를 사용하지 않아도 되는 점이 눈에 띄었습니다. 원래는 기숙형을 알아보고 있었는데, 인사교는 기숙형은 아니지만 주거비를 지원해 줘서 오게 되었습니다."},{"q":"기존 전공이 이쪽이신가요?","a":"아니요, 원래 전공은 경영학입니다. 이쪽이랑은 완전 다른 문과 출신이에요!"},{"q":"그럼 AI를 배우기 전에는 AI에 대해서 어떻게 생각하고 계셨나요?","a":"사실 할루시네이션 때문에 완전히 믿진 않았습니다. 그럼에도 기존 업무에서 많은 도움이 되어서, AI가 없으면 변화하는 미래를 대비할 수 없을 거라고 생각했어요."},{"q":"그럼 어느 정도 배운 지금 시점에서는 어떻게 생각하시는지 궁금해요.","a":"할루시네이션이나 부정확한 정보가 없는 AI도 기술적으로 만들 수 있다는 방법을 알았어요. 이 분야에 대해서 더 알고 나면 AI를 더 잘 활용해서 많은 도움을 받을 수 있겠다고 생각하고 있습니다."},{"q":"현재 학교 내에서 태성님의 '전공'이라고 할 수 있는 데이터 분석반에 들어가신 계기가 궁금해요!","a":"AI의 기본은 데이터에서 시작한다고 생각했어요. 그리고 향후 취업적인 면에서도 유리할 거라고 생각했습니다."},{"q":"그렇다면 이 인터뷰를 보실 다른 분들을 위해 데이터 분석반에서 지금까지 어떤 걸 배우셨는지, 혹은 배우고 계신 것을 소개해 주실 수 있나요?","a":"SQL, 통계학, 머신러닝과 딥러닝, 컴퓨터 관련 지식과 그 외 AI/데이터 분석 관련된 광범위한 스킬들을 배웠습니다."},{"q":"문과 출신이라고 하셨는데 통계학은 안 어려우셨나요?","a":"확실히 원래 알던 통계와는 다르긴 하지만, 그래도 경영 통계에서 배웠던 게 많은 도움이 되었습니다."},{"q":"데이터 분석가들은 분석할 때 자기만의 루틴이 있다고 하던데, 태성님도 태성님만의 분석 루틴이 있으신가요?","a":"아직 배운 지 얼마 되지 않아서 루틴이라고 하기엔 뭐하지만, 우선 정확한 학술 자료를 먼저 찾아보고 AI에게도 관련된 자료가 있는지 찾을 것을 요청합니다. 그리고 인터넷 서치로 다른 사람들의 자료를 참고해요."},{"q":"태성님은 분석 후 얻은 인사이트 중 기억에 남는 것이 있으신가요?","a":"대학 전공서로 배운 이론과 실제 분석은 결과론적으로 차이가 많이 난다는 점이 기억에 남습니다."},{"q":"예를 들어 어떤 느낌인가요?","a":"이론은 가정을 전제로 배우기 때문에 실제와 차이가 난다는 걸 알고는 있습니다. 하지만 실제 시장에서 일어나는 일이 데이터 분석을 거쳐 가면 왜 그런 차이가 나는지 세부적으로 분석할 수 있다는 것이라고 말씀드릴 수 있을 것 같아요."},{"q":"태성님이 생각하시기에 데이터 분석가가 가져야 할 가장 중요한 역량은 무엇인가요?","a":"우선 분석하고자 하는 영역의 도메인 지식이 있어야 해요. 그리고 논리적, 비판적 사고도 굉장히 중요합니다. 마지막으로 협업을 위해서는 소통 능력과 같은 소프트 스킬도 꼭 갖춰야 한다고 생각해요. 자신의 의견도 내려놓을 줄 알아야 하고요."},{"q":"이번엔 인사교에 관련된 질문을 드릴게요. 매일 4시에 진행되는 커리어업 시간에 대한 생각이 궁금합니다.","a":"교육생들에게 정말 유의미한 시간이라고 생각합니다. 다만 특강을 선택적으로 들으면 좋겠다고 생각했는데, 최근엔 듣고 싶은 강의만 들을 수 있어서 더 좋은 것 같아요. 추가적으로 지금은 온라인 강의라서 오프라인보다 한계점이 있는 것 같아서, 온라인 실시간보다는 동영상으로 제공해 주는 게 더 나을 것 같기도 해요."},{"q":"이제 인사교 6기 과정의 절반을 지났는데, 다니시면서 좋았던 점이 있으시다면요?","a":"이렇게 학생 수가 많은 부트캠프를 아직은 본 적이 없는데, 학생 수가 많다는 게 재밌는 점인 것 같아요. 그리고 불편 사항에 대한 즉각적인 피드백이 있는 것과 건물 내에 식당 등 편의시설이 잘 되어 있는 점도 좋습니다."},{"q":"그렇다면 반대로 힘들었거나 불편했던 점도 있으셨나요?","a":"노트북과 모니터가 지금도 좋지만 조금만 더 최신화가 되면 더욱 좋을 것 같습니다. 그리고 공부 외적으로 이력서나 포트폴리오 피드백이 필요할 때 바로 해 줄 수 있는 전문 인력이 상주해 있으면 좋겠어요."},{"q":"이제 수료까지 약 2달의 시간이 남았는데, 수료 후의 목표가 있으신가요?","a":"당연히 취업 혹은 창업이 목표이고요. 아니면 영역을 넓혀서 저의 일을 더욱 효율적으로 할 수 있는 도메인을 가지고 싶습니다."},{"q":"그게 장기이자 단기 목표인가요?","a":"장기 목표라고 하면 조금 더 거창하게, 대한민국의 상위 1%가 되는 게 목표입니다. ㅎ"},{"q":"마지막으로 하고 싶으신 말씀 듣고 인터뷰 마무리하겠습니다.","a":"이왕 공부하는 거, 지금 하고 있는 공부가 반드시 도움이 될 거라고 생각하니까 즐겁게 공부하고 싶습니다."}]	\N	\N	\N	PUBLISHED	\N	1	2026-10-19 14:27:07.726857	2026-10-19 14:27:07.726857	2026-10-19 14:27:07.726857	\N
11	6	조**	데이터 분석반	'AI를 이해하는 수준'에서 '실무에 쓰는 전문가'로	AI와 데이터로 커리어를 넓히고 싶어 지원했어요. 비전공자라 수학과 코딩이 낯설었지만 팀 스터디로 채웠고, 데이터 분석 준전문가 자격증을 땄어요.	[{"q":"인공지능사관학교에 지원하게 된 계기와 처음 입학했을 때 느낌은 어땠나요?","a":"앞으로는 AI와 데이터 분야로 커리어를 확장하고 싶다는 목표가 있었습니다. 처음엔 낯설고 어렵지 않을까 걱정했는데, 체계적인 커리큘럼과 다양한 배경의 동료들을 만나면서 오히려 기대감이 커졌습니다."},{"q":"3개월 차인 지금, 예상했던 것과 달라진 점이 있나요?","a":"처음에는 기초 위주로만 배울 거라 생각했는데, 실습 위주 수업 덕분에 예상보다 빠르게 실무 감각을 익힐 수 있었습니다. 특히 프로젝트 중심 학습을 통해 실제 현업과 가까운 경험을 쌓을 수 있었던 점이 달랐습니다."},{"q":"가장 흥미로웠던 수업이나 주제는 무엇이었나요?","a":"머신러닝 모델을 직접 실습해보면서 데이터 분석 과정을 경험한 것이 가장 흥미로웠습니다. 단순히 이론으로 끝나는 게 아니라, 데이터를 다루고 결과를 시각화하는 과정이 인상 깊었습니다."},{"q":"데이터 분석반에서 주로 배운 점과 특징은 무엇인가요?","a":"데이터 분석반은 기초 이론부터 프로젝트까지 단계적으로 학습할 수 있었고, 무엇보다 실습 비중이 높아 '배운 것을 바로 적용해본다'는 특징이 있습니다. 이 점 덕분에 빠르게 감각을 익힐 수 있었습니다."},{"q":"수업이나 프로젝트 진행 중에 어려웠던 점과 극복 방법은?","a":"비전공자로서 수학과 코딩이 가장 낯설었습니다. 하지만 팀 스터디와 반복 학습을 통해 개념을 보완했고, 동료들과 함께 문제를 해결하면서 자신감을 얻을 수 있었습니다."},{"q":"과정 중 자격증 취득이나 성취한 성과가 있나요?","a":"데이터 분석 준전문가 자격증을 취득했습니다. 또한 프로젝트 수행 과정에서 데이터 기반 문제 해결 경험을 쌓으면서, 실제 업무에 적용할 수 있는 역량을 키웠습니다."},{"q":"협업 프로젝트나 팀 활동에서 배운 교훈이 있다면?","a":"협업에서는 기술보다도 커뮤니케이션이 더 중요하다는 걸 느꼈습니다. 역할 분담을 명확히 하고 의견을 조율하는 과정에서, 서로의 강점을 살려야 프로젝트가 원활히 진행된다는 걸 배웠습니다."},{"q":"데이터 분석반을 추천한다면 어떤 사람에게 어울릴까요?","a":"자기주도적으로 학습할 수 있고, 새로운 도전에 두려움이 없는 분들에게 추천하고 싶습니다. 실습과 프로젝트 위주라서 적극적으로 참여할수록 얻는 게 많습니다."},{"q":"인사교 과정을 수료한 후 어떤 계획을 가지고 있나요?","a":"과정 수료 후에는 데이터 분석과 AI 관련 직무로 전환할 계획입니다. 실무와 가까운 경험을 쌓았기 때문에 현업에서 바로 적용할 수 있도록 준비 중입니다."},{"q":"이 과정을 통해 본인의 커리어 목표가 어떻게 달라졌나요?","a":"처음에는 'AI를 이해하는 수준'이 목표였다면, 지금은 'AI를 실무에 활용할 수 있는 전문가'로 성장하는 것이 제 목표로 구체화되었습니다."}]	\N	\N	\N	PUBLISHED	\N	1	2026-10-19 14:27:07.833164	2026-10-19 14:27:07.833164	2026-10-19 14:27:07.833164	\N
13	6	안**	AI 비즈니스반	요식업 창업을 꿈꾸다 AI 미디어 사업으로	경찰을 꿈꾸다 카페 · 족발집 등 현장에서 오래 일했어요. 인사교에서 AI의 매력을 알게 되어 사업자를 내고 인터넷 신문사를 열었어요.	[{"q":"인공지능사관학교에 지원하게 된 계기와 처음 입학했을 때 느낌은 어땠나요?","a":"어릴 때부터 경찰을 목표로 했지만 진로가 틀어지면서 카페·족발집 등 다양한 일을 거쳤다. 창업을 목표로 현장에서 오래 일했지만 근무 조건 문제로 지치게 되었고, 새로운 방향을 찾던 중 인공지능사관학교를 알게 되어 지원하게 됐다."},{"q":"3개월 차인 지금, 예상했던 것과 달라진 점이 있나요?","a":"처음에는 기대가 컸고 \\"AI 마스터가 되겠다\\"는 막연한 목표로 입학했다. 다만 3개월간 수강하며 운영 측 소통이 다소 부족하다는 점을 체감했다. 해커톤 일정이 사전에 많은 내용이 공유되지 않아 급하게 준비해야 하는 상황이 생겼었다."},{"q":"가장 흥미로웠던 수업이나 주제는 무엇이었나요?","a":"가장 흥미로웠던 주제는 프롬프트 제작 과정이었다. 평소 노코드 툴을 많이 사용했지만, 프롬프트 품질과 결과의 차이를 몸소 경험하며 특히 강한 인상을 받았다."},{"q":"비즈니스 반에서 주로 배운 점과 특징은 무엇인가요?","a":"비즈니스 반에 대한 소감으로는 \\"도메인 지식을 넓히는 데는 도움이 되지만 실질적 기술은 부족하게 느껴질 때가 있었다\\". 다른 반에서 기초 기술을 익힌 뒤 오면 더 큰 시너지가 있을 것이라 생각합니다."},{"q":"수업이나 프로젝트 진행 중에 어려웠던 점과 극복 방법은?","a":"프로젝트 과정에서 어려웠던 점으로는 코드를 그대로 입력해도 실행이 되지 않는 상황이 반복된 것이었다. 그는 이를 해결하기 위해 제미나이 등을 적극 활용하며 문제를 빠르게 해결했다."},{"q":"과정 중 자격증 취득이나 성취한 성과가 있나요?","a":"수강 중 자격증 취득은 없지만, 사업자를 직접 내고 인터넷 신문사 등록을 완료하는 등 새로운 진로 방향을 실행에 옮기고 있다."},{"q":"협업 프로젝트나 팀 활동에서 배운 교훈이 있다면?","a":"협업 경험에서 얻은 가장 큰 교훈은 \\"광주 사투리가 상대에게 화난 말투로 들릴 수 있다\\"는 점이었다. 전국에서 모인 교육생들과 일하며 커뮤니케이션 방식의 중요성을 깨달았다고 말했다."},{"q":"비즈니스반을 추천한다면 어떤 사람에게 어울릴까요?","a":"비즈니스 반은 이미 사업체를 가지고 있으나 개발적 기반이 부족한 사람, 혹은 비즈니스 모델·전략적 사고를 강화하고 싶은 개발자에게 가장 적합하다고 추천했다. 즉, 기술 기반 창업 준비자에게 실용적인 과정이라고 설명했다."},{"q":"인사교 과정을 수료한 후 어떤 계획을 가지고 있나요?","a":"수료 이후에는 신규로 개설한 인터넷 신문사를 본격적으로 성장시키는 것이 목표다. 다양한 분야의 인물을 만나 인터뷰 콘텐츠를 제작하고, 플랫폼 영향력을 확장해 나갈 계획을 갖고 있다."},{"q":"이 과정을 통해 본인의 커리어 목표가 어떻게 달라졌나요?","a":"이 과정을 통해 커리어 목표가 명확해졌다. 원래는 요식업 창업을 고민했지만, 지금은 밤을 새도 즐거울 만큼 AI 분야가 매력적이라고 말한다. 기존의 창업 의지는 그대로 유지하되, 이제는 \\"AI 기반 미디어 사업\\"으로 방향이 분명히 바뀌었다."}]	\N	\N	\N	PUBLISHED	\N	1	2026-10-19 14:27:07.877688	2026-10-19 14:27:07.877688	2026-10-19 14:27:07.877688	\N
7	6	신**	자연어 처리반	새로운 도전이던 AI, 이제는 자연어 처리 전문가를 꿈꿔요	기대와 긴장 속에 시작한 인공지능 공부였어요. LLM 수업과 프로젝트를 거치며 기술을 배우는 데서 나아가 더 깊이 연구하고 싶어졌어요.	[{"q":"인공지능사관학교에 들어온 첫 느낌은 어땠나요?","a":"처음에는 기대와 긴장이 공존했어요. 인공지능이라는 분야가 저에게는 새로운 도전이었기 때문에."},{"q":"세 달 동안 가장 인상 깊었던 수업은 무엇인가요?","a":"저는 LLM 모델 수업이 제일 흥미로웠어요. GPT, Claude, Grok 같은 모델들에 대해 깊이 있게 배울 수 있었거든요."},{"q":"프로젝트 경험은 어땠나요?","a":"프로젝트를 통해 실무에 가까운 경험을 할 수 있었고, 여러 사람과 협력하며 문제를 해결하는 과정에서 많은 성장을 느꼈어요. 이런 경험들이 앞으로의 경력에 큰 도움이 될 것 같아요."},{"q":"팀워크와 협업에서 느낀 점은?","a":"코드 작성이나 데이터 분석도 중요하지만, 팀원 간의 원활한 소통이 정말 중요하더라고요."},{"q":"진로 목표는 어떻게 달라졌나요?","a":"처음에는 단순히 기술을 배우는 것이 목표였지만, 지금은 더 깊이 있는 연구를 하고 싶은 마음이 커졌어요. 특히, 자연어 처리 분야에서 전문가가 되고 싶습니다."},{"q":"후배들에게 하고 싶은 말은?","a":"인공지능 분야에 관심이 있다면 꼭 도전해보세요! 정말 많은 것을 배울 수 있습니다."}]	\N	\N	\N	PUBLISHED	\N	1	2026-10-19 14:27:07.75392	2026-10-19 14:27:07.75392	2026-10-19 14:27:07.75392	\N
14	6	김**	컴퓨터 비전 B반	ChatGPT만 알던 제가 객체 탐지에 빠지기까지	과정을 시작할 땐 AI라고 하면 ChatGPT 정도만 알았어요. 6개월 동안 CNN과 객체 탐지를 배우며 직접 개발해 보고 싶은 분야가 생겼어요.	[{"q":"간단하게 자기소개 먼저 부탁드릴게요.","a":"안녕하세요. 컴퓨터 비전 B반에서 수업을 듣고 있는 김**입니다."},{"q":"인공지능사관학교를 알게 되신 계기가 궁금해요.","a":"스마트인재개발원에 계시는 지인분께 광주 인사교에 대한 소식을 듣고 6기 과정에 신청하게 됐습니다."},{"q":"이 과정을 배우기 전에 AI에 대해서는 얼마나 알고 계셨나요?","a":"많이 알지는 못했고, ChatGPT 정도만 알고 있었습니다."},{"q":"그렇다면 과정이 끝나가는 지금, AI에 대해 많이 알게 되셨나요?","a":"6개월의 수업을 받고 생각보다 많은 AI 모델이 있다는 것을 알게 되었습니다. 또한 기술의 흐름이 자주 바뀌다 보니 뉴스나 최신 동향을 꾸준히 확인해야 한다는 걸 깨달았어요."},{"q":"현재 컴퓨터 비전반에서 공부하고 계시는데, 많은 트랙 중에 '컴퓨터 비전'을 고르신 이유를 알고 싶어요.","a":"카메라를 통해 객체 탐지 모델을 활용해서 탐지·분석하는 서비스의 영상을 본 적이 있습니다. 그 영상을 보고 관심이 생겨서 신청하게 됐어요."},{"q":"처음 '컴퓨터 비전'이라는 걸 들었을 때 가장 먼저 어떤 걸 떠올리셨어요?","a":"저는 사람의 눈, 시각을 떠올렸습니다."},{"q":"지금까지 배운 것 중 가장 인상 깊었던 것을 하나만 소개해주실 수 있나요?","a":"이미지 분류, 객체 탐지를 통한 사람 인식 등 시각적 데이터를 분석하는 딥러닝 알고리즘인 CNN이라는 기술을 배울 때가 가장 재밌었습니다."},{"q":"시각적 데이터를 활용하는 기술이라면 일상생활에서 많이 쓰일 것 같은데, 주변에서 비전 기술이 쓰이고 있다는 걸 느꼈던 순간이 있나요?","a":"저희가 늘 사용하고 있는 스마트폰만 봐도 Face ID가 사용되고 있죠. 일상생활에 가장 잘 녹아있는 케이스인 것 같아요."},{"q":"카메라나 영상과 관련된 기술 중에 특히 관심 있는 분야가 있으신가요?","a":"저 같은 경우엔 카메라 기반 AI 기술 중 객체 탐지 분야에 흥미를 많이 느꼈고, 이미지나 영상 속에서 사람이나 물체를 자동으로 식별하고 위치까지 찾아내는 과정이 가장 재밌게 느껴졌습니다. 객체 탐지 기술을 직접 개발해보고 싶어요."},{"q":"지금까지 컴퓨터 비전을 공부하며 가장 어려웠던 부분이 있었다면요?","a":"아무래도 처음 보는 모델도 많았고 개념적으로 제가 많이 부족했는데, 수업 자료를 참고해서 개념 정리를 하며 부족한 부분을 채우려고 노력했어요."},{"q":"인사교에 있는 다양한 트랙들 중 협업해보고 싶은 반은 어떤 반인가요?","a":"자연어처리반과 협업해보고 싶어요. 자연어 분석과 CNN 기반 모델로 어떤 서비스를 만들 수 있을지가 궁금합니다."},{"q":"이제 수료를 정말 코앞에 두고 계신데, 6개월 동안 인사교를 다니며 가장 좋았던 점을 말씀해주세요.","a":"교육생들에게 지원해주는 부분이 많아 좋았습니다. 특히 온라인·오프라인 해커톤이 굉장히 좋은 경험이었다고 생각해요."},{"q":"곧 있을 수료식 후 목표가 있으시다면요?","a":"6개월 동안 인사교에서 배운 것들을 바탕으로 좋은 곳에 취업할 수 있게끔 본격적으로 취업 준비를 할 것 같습니다."}]	\N	\N	\N	PUBLISHED	\N	1	2026-10-19 14:27:07.899619	2026-10-19 14:27:07.899619	2026-10-21 09:10:34.02332	\N
